package com.cpf.starter.tcp;import java.io.*;import java.nio.file.*;import java.security.*;import java.util.concurrent.atomic.AtomicReference;import javax.net.ssl.*;
public final class KeyStoreCpfTcpTlsContextProvider implements CpfTcpTlsContextProvider {private final Path keyStore,trustStore;private final char[] keyPassword,trustPassword;private final AtomicReference<State> state=new AtomicReference<>();public KeyStoreCpfTcpTlsContextProvider(Path k,char[] kp,Path t,char[] tp){keyStore=k;keyPassword=kp.clone();trustStore=t;trustPassword=tp.clone();reload();}public synchronized void reload(){try{KeyStore ks=load(keyStore,keyPassword);KeyStore ts=load(trustStore,trustPassword);KeyManagerFactory km=KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());km.init(ks,keyPassword);TrustManagerFactory tm=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());tm.init(ts);SSLContext c=SSLContext.getInstance("TLSv1.3");c.init(km.getKeyManagers(),tm.getTrustManagers(),new SecureRandom());String v=Files.getLastModifiedTime(keyStore).toMillis()+":"+Files.getLastModifiedTime(trustStore).toMillis();state.set(new State(c,v));}catch(Exception ex){throw new IllegalStateException("TCP TLS material reload failed",ex);}}private static KeyStore load(Path p,char[] password)throws Exception{if(p==null||!Files.isRegularFile(p))throw new IllegalStateException("TLS store missing: "+p);KeyStore s=KeyStore.getInstance("PKCS12");try(InputStream in=Files.newInputStream(p)){s.load(in,password);}return s;}public SSLContext current(){return state.get().context;}public String keyVersion(){return state.get().version;}private record State(SSLContext context,String version){} }
